import type { Workspace } from './workspace-model';

export const BusinessCalendarStatusKeyToLabel = {
  'Active': 'Active',
  'Inactive': 'Inactive'
} as const;
export type BusinessCalendarStatusKey = keyof typeof BusinessCalendarStatusKeyToLabel;

export interface BusinessCalendar {
  /**
   * @displayName Business Calendar ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  name1: string;
  /**
   * @displayName Calendar Code
   * @validationRule Required for create/update operations
   */
  calendarCode: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: BusinessCalendarStatusKey;
  /**
   * @displayName Time Zone
   * @validationRule Required for create/update operations
   */
  timeZone: number;
  /**
   * @displayName Weekly Schedule Code
   * @validationRule Required for create/update operations
   */
  weeklyScheduleCode: string;
  /**
   * @displayName Workspace
   * @validationRule Required for create/update operations
   */
  workspace: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _BusinessCalendar = 'BusinessCalendar' as const;